import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise a constant function (R = 2/3)."""
    if start is not None:
        return np.asarray(start, dtype=float)
    return np.ones(50)

import numpy as np
import time
from scipy.optimize import minimize_scalar


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.convolve(h, h)
    # pad with zeros
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _gauss(N, sigma):
    x = (np.arange(N) + 0.5) / N
    return np.exp(-((x - 0.5) / sigma) ** 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_R = -1.0
    best_info = None

    def consider(h, info):
        nonlocal best_h, best_R, best_info
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = np.array(h, dtype=float)
            best_info = info
        return r

    # fallback: start
    if start is not None:
        try:
            consider(np.asarray(start, dtype=float), "start")
        except Exception:
            pass

    Ns = [50, 100, 200, 400, 800]
    # coarse sigma grid
    sigmas = np.geomspace(0.02, 0.5, 25)

    # initial scan
    for N in Ns:
        if time.process_time() > deadline:
            break
        for s in sigmas:
            if time.process_time() > deadline:
                break
            h = _gauss(N, s)
            consider(h, (N, s))

    # refine each N with minimize_scalar, iterating until budget
    # order: refine smaller Ns first, then larger; repeat
    while time.process_time() < deadline:
        progressed = False
        for N in Ns:
            if time.process_time() > deadline:
                break
            # find current best sigma for this N from best_info if matches, else scan
            # do a bounded scalar minimization
            def obj(logs):
                return -_R(_gauss(N, np.exp(logs)))

            try:
                res = minimize_scalar(
                    obj,
                    bounds=(np.log(0.02), np.log(0.5)),
                    method="bounded",
                    options={"xatol": 1e-6},
                )
                s = float(np.exp(res.x))
                h = _gauss(N, s)
                consider(h, (N, s))
                progressed = True
            except Exception:
                pass
            if time.process_time() > deadline:
                break
        if not progressed:
            break

    if best_h is None:
        return np.ones(50)
    return best_h
